import { NextResponse, type NextRequest } from "next/server";
import { gone } from "./content/gone";

/**
 * Deliberately retired paths from the previous site answer 410 Gone, so search engines drop them
 * promptly instead of retrying a 404. The list is generated by scripts/build-migration.mjs.
 */
export function proxy(req: NextRequest) {
  if (gone.includes(req.nextUrl.pathname)) {
    return new NextResponse(
      '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex"><title>Page removed — Highland Cabinetry</title></head><body style="font-family:system-ui;padding:3rem;max-width:40rem;margin:auto"><h1>This page has been removed.</h1><p><a href="/">Go to the Highland Cabinetry homepage</a></p></body></html>',
      { status: 410, headers: { "content-type": "text/html; charset=utf-8", "x-robots-tag": "noindex" } },
    );
  }
  return NextResponse.next();
}

export const config = { matcher: ["/oops/:path*", "/iframe-36/:path*", "/oops", "/iframe-36"] };
